function ev(values, probs){
  if(!Array.isArray(values)||!Array.isArray(probs)||values.length!==probs.length||!values.length) return {error:'数组等长且非空'};
  var s=0; for(var i=0;i<values.length;i++){ if(!(probs[i]>=0)) return {error:'概率须非负'}; s+=values[i]*probs[i]; }
  return {ev:Math.round(s*1000)/1000, variance:variance(values,probs)}; }
function variance(values, probs){
  var mean=0,sp=0; for(var i=0;i<values.length;i++) mean+=values[i]*probs[i];
  for(var i=0;i<values.length;i++) sp+=probs[i]*Math.pow(values[i]-mean,2);
  return Math.round(sp*1000)/1000; }
var EXPORTS={ev:ev, variance:variance};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ExpectedValueForgePure = EXPORTS; }
